parallel::mclapply(cases, function(case) {
    fit <- suppressWarnings(ml3_fit(case))
    inputs <- ml3_level_inputs(fit, case)
    list(posteriors = inputs$posteriors, modal = inputs$modal, values = inputs$values, ids = inputs$ids, clusters = inputs$clusters, step1_log_likelihood = fit$log_likelihood, entropy = ml3_entropy(inputs$posteriors), modal_counts = tabulate(inputs$modal, ncol(inputs$posteriors)))
}, mc.cores = 2L, mc.preschedule = FALSE)

parallel::mclapply(sweep, function(case) {
    fit <- suppressWarnings(ml3_fit(case))
    list(posteriors = unname(fit$subject_posteriors), modal = fit$subject_profiles, step1_log_likelihood = fit$log_likelihood, entropy = ml3_entropy(fit$subject_posteriors), modal_counts = tabulate(fit$subject_profiles, case$spec$k))
}, mc.cores = 2L, mc.preschedule = FALSE)

parallel::mclapply(seq_len(nrow(grid)), function(i) {
    fit <- suppressWarnings(montecarlo_fit(cases[[grid$case[i]]], seed = grid$seed[i], n_starts = grid$n_starts[i]))
    fit$log_likelihood
}, mc.cores = cores, mc.preschedule = FALSE)
